"use client";

import {
	Children,
	isValidElement,
	type CSSProperties,
	type HTMLAttributes,
	type ReactNode,
	useId,
	useState,
} from "react";
import { cardParts } from "./card.styles";
import { cn } from "@/lib/utils";

export type CardStackProps = Omit<HTMLAttributes<HTMLElement>, "children"> & {
	/** The cards, newest first. Each child becomes a list item. */
	children: ReactNode;
	/** What the cards are, for the toggle ("Show all 4 notifications"). Default "cards". */
	noun?: string;
	/** How many cards peek out behind the first while collapsed. Default 2. */
	peek?: number;
	/** Controlled state. Pair with `onExpandedChange`. */
	expanded?: boolean;
	defaultExpanded?: boolean;
	onExpandedChange?: (expanded: boolean) => void;
	/** The toggle's text. Defaults to "Show all N {noun}" and "Show less". */
	showLabel?: string;
	hideLabel?: string;
};

/**
 * Cards piled behind the first, each a little smaller, that spread into a list. The toggle is a
 * real button with `aria-expanded`; while collapsed its hit area covers the whole pile, so a click
 * or tap anywhere on it opens the list. The cards behind are `inert` while collapsed, so neither
 * Tab nor a screen reader lands on what you cannot see. Keep links and buttons out of the first
 * card, or they sit under the toggle until the stack is open.
 *
 * The motion is CSS: each item's height animates between its peek and `auto` with
 * `interpolate-size`, and the cards scale back to full size, on the panel spring. Cards of similar
 * height stack best.
 */
export function CardStack({
	children,
	noun = "cards",
	peek = 2,
	expanded,
	defaultExpanded = false,
	onExpandedChange,
	showLabel,
	hideLabel = "Show less",
	className,
	style,
	...rest
}: CardStackProps) {
	const [own, setOwn] = useState(defaultExpanded);
	const open = expanded ?? own;
	const listId = useId();
	const items = Children.toArray(children);

	const set = (next: boolean) => {
		if (expanded === undefined) setOwn(next);
		onExpandedChange?.(next);
	};

	return (
		<section
			{...rest}
			data-expanded={open ? "" : undefined}
			className={cn(cardParts.stack, className)}
			style={{ ...style, "--_count": items.length, "--_peeks": peek } as CSSProperties}
		>
			<ol id={listId} className={cardParts.stackList}>
				{items.map((child, index) => (
					<li
						key={childKey(child, index)}
						className={cardParts.stackItem}
						style={{ "--_i": index } as CSSProperties}
						data-hidden={!open && index > peek ? "" : undefined}
						inert={!open && index > 0}
					>
						{child}
					</li>
				))}
			</ol>
			{items.length > 1 ? (
				<button
					type="button"
					className={cardParts.stackToggle}
					aria-expanded={open}
					aria-controls={listId}
					onClick={() => set(!open)}
				>
					{open ? hideLabel : (showLabel ?? `Show all ${items.length} ${noun}`)}
					<span className={cardParts.chevron} aria-hidden="true" />
				</button>
			) : null}
		</section>
	);
}

/** A child's own key when it has one, so reordering keeps each card's state with it. */
function childKey(child: ReturnType<typeof Children.toArray>[number], index: number) {
	return isValidElement(child) && child.key !== null ? child.key : index;
}

export type CardSize = "sm" | "default" | "lg";

export const cardSizes = ["sm", "default", "lg"] as const satisfies readonly CardSize[];

/**
 * The class list for a Card. The look lives in `card.css` (your global CSS, when installed from the
 * registry) on top of the shared surface in `control.css`, so React, Solid and plain HTML all get the
 * same card from these names:
 *
 *   <div class="rx-surface rx-card"><div class="rx-card-header">...</div></div>
 *
 * Padding is 12, 16 or 20px including the 1px edge (Figma's Kanban, Option and Stat cards).
 */
export function cardClass(size: CardSize = "default") {
	return `rx-surface rx-card${size === "default" ? "" : ` rx-card-${size}`}`;
}

/** Class names for the parts of a Card and its animated variants, for markup written by hand. */
export const cardParts = {
	header: "rx-card-header",
	title: "rx-card-title",
	description: "rx-card-description",
	action: "rx-card-action",
	content: "rx-card-content",
	footer: "rx-card-footer",
	/**
	 * Put it on the one link, button or label that owns the card: its hit area stretches over the
	 * whole card, the card gets hover, press and focus feedback, and a checked input inside it marks
	 * the card selected. Other controls in the card stay on top and keep working.
	 */
	target: "rx-card-target",
	/** TiltCard: leans toward the pointer in 3D, with a glare that follows it. */
	tilt: "rx-card-tilt",
	/** SpotlightCard: a soft light and a lit edge follow the pointer. */
	spotlight: "rx-card-spotlight",
	/** ExpandableCard: a `<details>` card whose content grows open. */
	expandable: "rx-card-expandable",
	summary: "rx-card-summary",
	chevron: "rx-card-chevron",
	/** CardStack: cards piled behind the first that spread into a list. */
	stack: "rx-card-stack",
	stackList: "rx-card-stack-list",
	stackItem: "rx-card-stack-item",
	stackToggle: "rx-card-stack-toggle",
} as const;

import type { HTMLAttributes, Ref } from "react";
import { type CardSize, cardClass, cardParts } from "./card.styles";
import { cn } from "@/lib/utils";

type Part<T extends string> = HTMLAttributes<HTMLElement> & {
	/** The element to render. */
	as?: T;
	ref?: Ref<HTMLElement>;
};

export type CardProps = Part<"div" | "article" | "section" | "aside" | "li"> & {
	/** Padding and spacing for every part: 12, 16 (default) or 20px. */
	size?: CardSize;
};

/**
 * A surface that holds one subject. The parts pad themselves on the inline axis, so a part can be
 * left out and an image placed directly inside runs edge to edge. Depth and radius follow the page
 * modes (`data-depth`, `data-radius`), not props.
 *
 * A card never takes focus itself. To make one clickable or selectable, put a link, button or label
 * inside with `cardParts.target`: it stretches over the card and the card answers hover, press,
 * focus and a checked input, all from CSS.
 */
export function Card({ as = "div", size = "default", className, ref, ...rest }: CardProps) {
	// One element type for the checker; the tag still renders as given.
	const Tag = as as "div";
	return (
		<Tag
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card"
			data-size={size}
			className={cn(cardClass(size), className)}
		/>
	);
}

/** Title and description, with an optional CardAction pinned to the top right. */
export function CardHeader({ as: Tag = "div", className, ref, ...rest }: Part<"div" | "header">) {
	return (
		<Tag
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card-header"
			className={cn(cardParts.header, className)}
		/>
	);
}

export function CardTitle({
	as: Tag = "div",
	className,
	ref,
	...rest
}: Part<"div" | "h2" | "h3" | "h4" | "h5" | "h6">) {
	return (
		<Tag
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card-title"
			className={cn(cardParts.title, className)}
		/>
	);
}

export function CardDescription({ as: Tag = "p", className, ref, ...rest }: Part<"p" | "div">) {
	return (
		<Tag
			{...rest}
			ref={ref as Ref<HTMLParagraphElement>}
			data-slot="card-description"
			className={cn(cardParts.description, className)}
		/>
	);
}

/** Sits beside the title and description inside CardHeader, such as a button or a badge. */
export function CardAction({ className, ref, ...rest }: Omit<Part<"div">, "as">) {
	return (
		<div
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card-action"
			className={cn(cardParts.action, className)}
		/>
	);
}

export function CardContent({ className, ref, ...rest }: Omit<Part<"div">, "as">) {
	return (
		<div
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card-content"
			className={cn(cardParts.content, className)}
		/>
	);
}

export function CardFooter({ as: Tag = "div", className, ref, ...rest }: Part<"div" | "footer">) {
	return (
		<Tag
			{...rest}
			ref={ref as Ref<HTMLDivElement>}
			data-slot="card-footer"
			className={cn(cardParts.footer, className)}
		/>
	);
}

"use client";

import type { DetailsHTMLAttributes, ReactNode, Ref, SyntheticEvent } from "react";
import { type CardSize, cardClass, cardParts } from "./card.styles";
import { cn } from "@/lib/utils";

export type ExpandableCardProps = Omit<DetailsHTMLAttributes<HTMLDetailsElement>, "title"> & {
	/** The always-visible heading. It is the toggle's accessible name. */
	title: ReactNode;
	/** A line under the title, also always visible. */
	description?: ReactNode;
	/** Padding and spacing, as on Card. */
	size?: CardSize;
	/** Starts open (uncontrolled). Pass `open` with `onOpenChange` to control it instead. */
	defaultOpen?: boolean;
	/** Called with the new state after the user (or `name` grouping) opens or closes it. */
	onOpenChange?: (open: boolean) => void;
	ref?: Ref<HTMLDetailsElement>;
};

/**
 * A card built on `<details>`: the summary row is the toggle, so the browser provides the button
 * role, the expanded state, Enter and Space, find-in-page opening and `name` grouping (only one of
 * a group open at a time). The content grows to its height on the panel spring with
 * `interpolate-size` and `::details-content`; browsers without them open it at once.
 */
export function ExpandableCard({
	title,
	description,
	size = "default",
	open,
	defaultOpen,
	onOpenChange,
	onToggle,
	className,
	children,
	ref,
	...rest
}: ExpandableCardProps) {
	const toggle = (event: SyntheticEvent<HTMLDetailsElement>) => {
		onToggle?.(event as Parameters<NonNullable<typeof onToggle>>[0]);
		onOpenChange?.(event.currentTarget.open);
	};

	return (
		<details
			{...rest}
			ref={ref}
			open={open ?? defaultOpen}
			onToggle={toggle}
			data-slot="card"
			data-size={size}
			className={cn(cardClass(size), cardParts.expandable, className)}
		>
			<summary className={cardParts.summary}>
				<span className={cardParts.header}>
					<span className={cardParts.title}>{title}</span>
					{description ? <span className={cardParts.description}>{description}</span> : null}
				</span>
				<span className={cardParts.chevron} aria-hidden="true" />
			</summary>
			<div className={cardParts.content}>{children}</div>
		</details>
	);
}

/** Where the pointer is over a box, from 0 (left or top edge) to 1 (right or bottom edge). */
export function pointerRatio(
	rect: { left: number; top: number; width: number; height: number },
	clientX: number,
	clientY: number,
) {
	return {
		x: rect.width ? clamp((clientX - rect.left) / rect.width) : 0.5,
		y: rect.height ? clamp((clientY - rect.top) / rect.height) : 0.5,
	};
}

/**
 * How far a TiltCard turns, in degrees, so the side under the pointer dips toward it. The centre is
 * flat; an edge turns by half of `max`, a corner on both axes.
 */
export function tiltAngles(ratio: { x: number; y: number }, max: number) {
	return { x: round((0.5 - ratio.y) * max), y: round((ratio.x - 0.5) * max) };
}

const clamp = (value: number) => Math.min(1, Math.max(0, value));
const round = (value: number) => Math.round(value * 100) / 100 || 0;

/** Writes the pointer's position over the element as `--_px` / `--_py` percentages. */
export function setPointerVars(node: HTMLElement, ratio: { x: number; y: number }) {
	node.style.setProperty("--_px", `${round(ratio.x * 100)}%`);
	node.style.setProperty("--_py", `${round(ratio.y * 100)}%`);
}

"use client";

import type { PointerEvent } from "react";
import { Card, type CardProps } from "./card";
import { cardParts } from "./card.styles";
import { pointerRatio, setPointerVars } from "./pointer";
import { cn } from "@/lib/utils";

export type SpotlightCardProps = CardProps;

/**
 * A Card with a soft light that follows a mouse or pen across it and lights up the edge nearest the
 * pointer. The pointer writes the position as CSS variables; the light, its fade and its color
 * (`--primary`, so `[--primary:var(--violet)]` recolors one card) are CSS. When a link or button
 * inside has keyboard focus, the light rests at the top so focus gets the same highlight.
 */
export function SpotlightCard({
	onPointerMove,
	onPointerLeave,
	className,
	...rest
}: SpotlightCardProps) {
	const follow = (event: PointerEvent<HTMLElement>) => {
		onPointerMove?.(event);
		if (event.pointerType === "touch") return;
		const node = event.currentTarget;
		setPointerVars(node, pointerRatio(node.getBoundingClientRect(), event.clientX, event.clientY));
		node.dataset.pointer = "";
	};

	const release = (event: PointerEvent<HTMLElement>) => {
		onPointerLeave?.(event);
		delete event.currentTarget.dataset.pointer;
	};

	return (
		<Card
			{...rest}
			className={cn(cardParts.spotlight, className)}
			onPointerMove={follow}
			onPointerLeave={release}
		/>
	);
}

"use client";

import type { PointerEvent } from "react";
import { Card, type CardProps } from "./card";
import { cardParts } from "./card.styles";
import { pointerRatio, setPointerVars, tiltAngles } from "./pointer";
import { cn } from "@/lib/utils";

export type TiltCardProps = CardProps & {
	/** The most the card turns at a corner, in degrees. Default 10. */
	max?: number;
	/** A soft highlight under the pointer. Default true. */
	glare?: boolean;
};

/**
 * A Card that leans toward a mouse or pen in 3D, with a glare that follows it, and springs back
 * flat when the pointer leaves. The pointer only writes CSS variables; the `transform` transition on
 * the magnetic spring does the motion and is off for touch, reduced motion and `data-motion="off"`.
 * It is decoration: it adds no focus stop and no role.
 */
export function TiltCard({
	max = 10,
	glare = true,
	onPointerMove,
	onPointerLeave,
	className,
	...rest
}: TiltCardProps) {
	const follow = (event: PointerEvent<HTMLElement>) => {
		onPointerMove?.(event);
		if (event.pointerType === "touch") return;
		const node = event.currentTarget;
		// offsetWidth/Height are the untransformed size, so the tilt does not skew the measurement.
		const rect = node.getBoundingClientRect();
		const ratio = pointerRatio(
			{
				left: rect.left + (rect.width - node.offsetWidth) / 2,
				top: rect.top + (rect.height - node.offsetHeight) / 2,
				width: node.offsetWidth,
				height: node.offsetHeight,
			},
			event.clientX,
			event.clientY,
		);
		const { x, y } = tiltAngles(ratio, max);
		node.style.setProperty("--_tilt-x", `${x}deg`);
		node.style.setProperty("--_tilt-y", `${y}deg`);
		setPointerVars(node, ratio);
		node.dataset.pointer = "";
	};

	const release = (event: PointerEvent<HTMLElement>) => {
		onPointerLeave?.(event);
		const node = event.currentTarget;
		node.style.removeProperty("--_tilt-x");
		node.style.removeProperty("--_tilt-y");
		delete node.dataset.pointer;
	};

	return (
		<Card
			{...rest}
			data-glare={glare ? "" : undefined}
			className={cn(cardParts.tilt, className)}
			onPointerMove={follow}
			onPointerLeave={release}
		/>
	);
}
